<template><view class="page"><view class="card"><input v-model="title" class="input" placeholder="签到任务标题" /><textarea v-model="description" class="textarea gap" placeholder="说明（可选）" /><button class="primary-btn" @click="submit">发布签到</button></view></view></template>
<script setup lang="ts">import{ref}from'vue';import{onLoad}from'@dcloudio/uni-app';import{api}from'@/services/api';const id=ref(0),title=ref(''),description=ref('');onLoad((o:any)=>id.value=Number(o.id));async function submit(){if(!title.value.trim())return uni.showToast({title:'请输入标题',icon:'none'});await api(`/activities/${id.value}/sign-tasks`,'POST',{title:title.value,description:description.value});uni.showToast({title:'发布成功'});setTimeout(()=>uni.navigateBack(),500)}</script><style scoped>.gap{margin-top:20rpx}</style>
